ON CONFLICT (sku) DO UPDATE SET nome=EXCLUDED.nome, subcategoria=EXCLUDED.subcategoria, preco=EXCLUDED.preco, preco_original=EXCLUDED.preco_original, peso=EXCLUDED.peso;

SELECT (SELECT MIN(id) FROM lojas), p.sku,
       CASE WHEN p.perecivel THEN CURRENT_DATE + (3 + (random()*12)::int) ELSE CURRENT_DATE + 180 END,
       10 + (random()*20)::int, 0
FROM produtos p WHERE NOT EXISTS (SELECT 1 FROM lotes l WHERE l.sku = p.sku);
